</div>
<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script id="rampart-strategy">
function createStrategy() {
  return { plan() { return []; } };
}
</script>
<script id="rampart-sim">
function rampartSimulate(createStrategy, seed, maxTicks) {
  const recorder = arguments[3];
  const ground = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
  const air = [[0,6],[21,6],[21,11],[23,11]];
  const routes = [ground, air].map(points => {
    let distance = 0;
    return points.slice(1).map(([x, y], index) => {
      const [fromX, fromY] = points[index];
      const start = distance;
      distance += 100 * (Math.abs(x - fromX) + Math.abs(y - fromY));
      return { x: fromX * 100 + 50, y: fromY * 100 + 50, start, end: distance,
        dx: Math.sign(x - fromX), dy: Math.sign(y - fromY) };
    });
  });
  const lengths = [4600, 2600];
  const types = ['"'bolt', 'cannon', 'frost', 'lance', 'flak'];
  const turretStats = [
    [50,26,8,300,0,0,false,3], [90,60,24,260,90,0,false,1],
    [70,10,12,240,0,30,false,3], [120,180,36,360,0,0,true,1],
    [80,40,10,320,70,0,false,2]
  ];
  const enemyTypes = ['grunt', 'runner', 'wisp', 'brute', 'splitter', 'mender', 'splitling'];
  const enemyStats = [
    [60,10,4,1,0,1,10], [40,20,4,1,0,2,4], [50,12,6,2,1,3,3],
    [150,6,9,3,0,4,3], [90,8,6,2,0,6,2], [70,8,7,2,0,8,1], [0,12,1,1,0,0,0]
  ];
  const slots = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],
    [14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]]
    .map(([x,y], slot) => ({ slot, x: x * 100 + 50, y: y * 100 + 50, turret: null }));
  function mulberry32(a) {
    return function () {
      a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a "'^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t; return (t ''^ (t >>> 14)) >>> 0;
    };
  }
  const draw = mulberry32(seed);
  const strategy = createStrategy();
  const log = [];
  const enemies = [];
  const queue = [];
  let tick = 0, wave = 0, gold = 250, baseHp = 10, id = 0, fallTick = -1, multiplier = 1000;
  let composition = makeWave(1), preview = composition;
  function makeWave(number) {
    const count = 4 + Math.floor(3 * number / 5);
    let weight = 0;
    for (let i = 0; i < 6; i++) if (enemyStats[i][5] <= number) weight += enemyStats[i][6];
    return Array.from({ length: count }, () => {
      let pick = draw() % weight;
      for (let i = 0; i < 6; i++) {
        if (enemyStats[i][5] > number) continue;
        if (pick < enemyStats[i][6]) return i;
        pick -= enemyStats[i][6];
      }
    });
  }
  function placeEnemy(enemy) {
    const path = routes[enemy.air];
    let segment = 0;
    while (segment < path.length - 1 && enemy.progress >= path[segment].end) segment++;
    const leg = path[segment];
    const distance = enemy.progress - leg.start;
    enemy.x = leg.x + distance * leg.dx;
    enemy.y = leg.y + distance * leg.dy;
    enemy.dx = leg.dx;
    enemy.dy = leg.dy;
  }
  function spawn(kind, number, maxHp, progress) {
    const [,speed,bounty,leak,airborne] = enemyStats[kind];
    const armor = kind === 0 ? Math.floor(number / 4) : kind === 3 ? 6 + number : 0;
    const enemy = { id: ++id, kind, wave: number, hp: maxHp, maxHp, speed, armor,
      air: airborne, bounty, leak, progress, age: 0, slow: 0 };
    placeEnemy(enemy);
    enemies.push(enemy);
  }
  function view(enemy) {
    return { id: enemy.id, type: enemyTypes[enemy.kind], hp: enemy.hp, maxHp: enemy.maxHp,
      x: enemy.x, y: enemy.y, air: enemy.air, armor: enemy.armor, speed: enemy.speed,
      slowed: enemy.slow > 0, remaining: lengths[enemy.air] - enemy.progress };
  }
  function copySlots() {
    return slots.map(({slot,x,y,turret}) => ({ slot, x, y, turret: turret ?
      { type: types[turret.kind], tier: turret.tier, spent: turret.spent } : null }));
  }
  function within(a, b, radius) {
    const dx = a.x - b.x, dy = a.y - b.y;
    return dx * dx + dy * dy <= radius * radius;
  }
  function apply(actions) {
    if (!Array.isArray(actions)) return;
    for (let i = 0; i < Math.min(32, actions.length); i++) {
      const action = actions[i];
      if (!action || !Number.isInteger(action.slot) || !slots[action.slot]) continue;
      const slot = slots[action.slot];
      const turret = slot.turret;
      if (action.op === '"'build' && "'!turret) {
        const kind = types.indexOf(action.type);
        if (kind < 0) continue;
        const [cost,damage,,range] = turretStats[kind];
        if (gold < cost) continue;
        gold -= cost;
        slot.turret = { kind, damage, range, tier: 1, spent: cost, cooldown: 0 };
        log.push([tick, '"'B', slot.slot, kind]);
        if (recorder) recorder.event(tick, 'B', { x: slot.x, y: slot.y, kind });
      } else if (action.op === 'upgrade' && turret && turret.tier < 3) {
        const cost = turretStats[turret.kind][0] * turret.tier;
        if (gold < cost) continue;
        gold -= cost;
        turret.spent += cost;
        turret.tier++;
        turret.damage = Math.floor(turret.damage * 16 / 10);
        turret.range += 30;
        log.push([tick, 'U', slot.slot, turret.tier]);
        if (recorder) recorder.event(tick, 'U', { x: slot.x, y: slot.y, kind: turret.kind });
      } else if (action.op === 'sell' && turret) {
        gold += Math.floor(turret.spent * 70 / 100);
        slot.turret = null;
        log.push([tick, 'S', slot.slot, 0]);
        if (recorder) recorder.event(tick, 'S', { x: slot.x, y: slot.y, kind: turret.kind });
      }
    }
  }
  function recordFrame() {
    recorder.frame(tick, {
      wave, gold, baseHp, preview: preview.map(kind => enemyTypes[kind]),
      turrets: slots.map(slot => slot.turret && { kind: slot.turret.kind, tier: slot.turret.tier }),
      enemies: enemies.map(enemy => ({ id: enemy.id, kind: enemy.kind, x: enemy.x, y: enemy.y,
        dx: enemy.dx, dy: enemy.dy, hp: enemy.hp, maxHp: enemy.maxHp, slow: enemy.slow }))
    });
  }
  if (recorder) recorder.board({ ground, air, slots: copySlots() });
  game: for (tick = 0; tick < maxTicks; tick++) {
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      wave++;
      if (wave > 1) multiplier = Math.floor(multiplier * 108 / 100);
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * wave;
      preview = makeWave(wave + 1);
      if (recorder) recorder.event(tick, 'W', { x: 2350, y: 1150, wave });
      apply(strategy.plan({ tick, wave, gold, baseHp, slots: copySlots(),
        enemies: enemies.map(view), nextWave: preview.map(kind => enemyTypes[kind]) }));
      composition.forEach((kind, index) => queue.push({
        tick: tick + 4 * index, wave, index, kind,
        hp: Math.floor(enemyStats[kind][0] * multiplier / 1000)
      }));
      queue.sort((a,b) => a.tick - b.tick || a.wave - b.wave || a.index - b.index);
      composition = preview;
    }

    while (queue.length && queue[0].tick === tick) {
      const next = queue.shift();
      spawn(next.kind, next.wave, next.hp, 0);
    }
    for (let i = 0; i < enemies.length;) {
      const enemy = enemies[i];
      enemy.progress += enemy.slow ? Math.floor(enemy.speed * 60 / 100) : enemy.speed;
      if (enemy.progress < lengths[enemy.air]) {
        placeEnemy(enemy);
        i++;
        continue;
      }
      enemies.splice(i, 1);
      baseHp -= enemy.leak;
      log.push([tick, 'L', enemy.id, baseHp]);
      if (recorder) recorder.event(tick, 'L', { x: 2350, y: 1150, baseHp, damage: enemy.leak });
      if (baseHp <= 0) {
        fallTick = tick;
        log.push([tick, 'F', wave, 0]);
        if (recorder) {
          recorder.event(tick, 'F', { x: 2350, y: 1150 });
          recordFrame();
        }
        break game;
      }
    }
    for (const enemy of enemies) {
      enemy.age++;
      if (enemy.kind "'!== 5 || enemy.age % 20 !== 0) continue;
      for (const other of enemies) {
        if (within(enemy, other, 150)) other.hp = Math.min(other.maxHp, other.hp + Math.floor(other.maxHp * 8 / 100));
      }
      if (recorder) recorder.event(tick, '"'H', { x: enemy.x, y: enemy.y, radius: 150 });
    }

    for (const slot of slots) {
      const turret = slot.turret;
      if ("'!turret || (turret.cooldown > 0 && --turret.cooldown > 0)) continue;
      const [,,period,,splash,slow,pierce,domains] = turretStats[turret.kind];
      const candidates = enemies.filter(enemy => (domains & (1 << enemy.air)) && within(slot, enemy, turret.range));
      if (!candidates.length) continue;
      let target;
      if (strategy.target) {
        const chosen = strategy.target({ slot: slot.slot, type: types[turret.kind], tier: turret.tier,
          x: slot.x, y: slot.y, range: turret.range }, candidates.map(view));
        target = candidates.find(enemy => enemy.id === chosen);
      }
      if (!target) {
        target = candidates[0];
        for (const enemy of candidates) {
          if (lengths[enemy.air] - enemy.progress < lengths[target.air] - target.progress) target = enemy;
        }
      }
      const hits = splash ? enemies.filter(enemy => (domains & (1 << enemy.air)) && within(target, enemy, splash)) : [target];
      for (const enemy of hits) {
        enemy.hp -= pierce ? turret.damage : Math.max(1, turret.damage - enemy.armor);
        if (slow) enemy.slow = slow;
      }
      turret.cooldown = period;
      if (recorder) recorder.event(tick, '"'T', { x: slot.x, y: slot.y, slot: slot.slot,
        toX: target.x, toY: target.y, air: target.air, kind: turret.kind, radius: splash });
      for (let i = 0; i < enemies.length;) {
        const enemy = enemies[i];
        if (enemy.hp > 0) {
          i++;
          continue;
        }
        enemies.splice(i, 1);
        gold += enemy.bounty;
        log.push([tick, 'K', enemy.id, slot.slot]);
        if (recorder) recorder.event(tick, 'K', { x: enemy.x, y: enemy.y, kind: enemy.kind, air: enemy.air });
        if (enemy.kind === 4) {
          const hp = Math.max(1, Math.floor(enemy.maxHp / 4));
          for (let j = 0; j < 3; j++) spawn(6, enemy.wave, hp, enemy.progress);
        }
      }
    }
    for (const enemy of enemies) if (enemy.slow > 0) enemy.slow--;
    if (recorder) recordFrame();
  }
  const score = Math.round(((fallTick < 0 ? maxTicks : fallTick) - 20) * 2.5) / 100;
  let hash = 0x811c9dc5;
  const serialized = JSON.stringify(log);
  for (let i = 0; i < serialized.length; i++) hash = Math.imul(hash "'^ serialized.charCodeAt(i), 0x01000193);
  return { score, fallTick, log, hash: (hash >>> 0).toString(16).padStart(8, '"'0') };
}
</script>
