cat > /tmp/rampart-check.py <<'EOF'
from pathlib import Path
import re, subprocess, sys
html = Path('index.html').read_text()
scripts = [re.search('<script id=\"rampart-'+name+'\">(.*?)</script>', html, re.S)[1] for name in ('strategy', 'sim')]
test = '''
const a = () => ({ plan(s) { const a = []; let g = s.gold; for (const sl of s.slots) if ("'!sl.turret && g >= 50) { a.push({op:"build",slot:sl.slot,type:"bolt"}); g -= 50; } return a; } });
const b = () => ({ plan(s) { return {1:[{op:"build",slot:3,type:"cannon"},{op:"build",slot:6,type:"frost"}],3:[{op:"upgrade",slot:3},{op:"build",slot:12,type:"flak"}],6:[{op:"build",slot:8,type:"lance"},{op:"sell",slot:6}]}[s.wave] || []; } });
for (const [strategy,seed] of [[a,42],[b,7]]) {const r=rampartSimulate(strategy,seed,12020);print(r.score,r.fallTick,r.log.length,r.hash,JSON.stringify(r.log.slice(0,6)));}
'"'''
harness = sys.argv[1] if len(sys.argv) > 1 else 'check'
if harness "'!= '"'check':
    test = Path(harness).read_text()
Path('/tmp/rampart-eval.js').write_text('\\n'.join(scripts+[test]))
subprocess.run(['/System/Library/Frameworks/JavaScriptCore.framework/Versions/A/Helpers/jsc', '/tmp/rampart-eval.js'], check=True)
EOF
python3 /tmp/rampart-check.py"

